(()=>{const key='gramin-service-branch',fallback=[{id:'narsipatnam',name:'Narsipatnam branch',latitude:17.667,longitude:82.612}],branches=()=>data?.settings?.branches?.length?data.settings.branches:fallback,read=()=>{try{const saved=JSON.parse(localStorage.getItem(key)||'null');return branches().find(x=>x.id===saved?.id)||branches()[0];}catch{return branches()[0];}},save=x=>localStorage.setItem(key,JSON.stringify(x));window.graminLocation={get:read};const update=()=>{const h=document.querySelector('header .location');if(!h)return;if(!localToken||!localUser||role!=='customer'){h.textContent='';return;}const current=read();h.innerHTML=`<label class="branch-picker">Service branch<select id="branch-select">${branches().map(x=>`<option value="${x.id}" ${x.id===current.id?'selected':''}>${x.name}</option>`).join('')}</select><small>Village suggestions within 50 km</small></label>`;document.querySelector('#branch-select').onchange=e=>{save(branches().find(x=>x.id===e.target.value));update();toast('Service branch changed. Village suggestions now use its 50 km area.');};};const admin=()=>{if(role!=='admin'||!data)return;const list=branches().map(x=>`${x.name}|${x.latitude}|${x.longitude}`).join('\n');app.insertAdjacentHTML('afterbegin',`<section class="card branch-admin"><div class="eyebrow">CUSTOMER SERVICE BRANCHES</div><h2>Branch dropdown</h2><p class="muted">Only these branches appear to customers. One per line: Branch name | latitude | longitude</p><form id="branch-form"><label class="field">Branches<textarea name="branches" required>${esc(list)}</textarea></label><button class="secondary" type="submit">Save branches</button></form></section>`);document.querySelector('#branch-form').onsubmit=e=>{e.preventDefault();try{const rows=new FormData(e.target).get('branches').split('\n').map(x=>x.split('|').map(y=>y.trim())).filter(x=>x.length===3&&x[0]);const next=rows.map(([name,latitude,longitude])=>({id:name.toLocaleLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),name,latitude:Number(latitude),longitude:Number(longitude)}));act('settings',{...data.settings,areas:data.settings.areas,branches:next});}catch{toast('Enter branches as name | latitude | longitude');}};};const baseRender=render;render=function(){baseRender();update();admin();};update();})();
